{
  "items": [
    {
      "name": "MvPolynomial.pderiv",
      "module_name": "Mathlib.Algebra.MvPolynomial.PDeriv",
      "kind": "definition",
      "type": "{R : Type u} → {σ : Type v} → [inst : CommSemiring R] → σ → Derivation R (MvPolynomial σ R) (MvPolynomial σ R)"
    },
    {
      "name": "MvPolynomial.mkDerivation",
      "module_name": "Mathlib.Algebra.MvPolynomial.Derivation",
      "kind": "definition",
      "type": "{σ : Type u_1} →\n  (R : Type u_2) →\n    {A : Type u_3} →\n      [inst : CommSemiring R] →\n        [inst_1 : AddCommMonoid A] →\n          [inst_2 : Module R A] →\n            [inst_3 : Module (MvPolynomial σ R) A] →\n              [IsScalarTower R (MvPolynomial σ R) A] → (σ → A) → Derivation R (MvPolynomial σ R) A"
    },
    {
      "name": "Polynomial.hasseDeriv",
      "module_name": "Mathlib.Algebra.Polynomial.HasseDeriv",
      "kind": "definition",
      "type": "{R : Type u_1} → [inst : Semiring R] → ℕ → Polynomial R →ₗ[R] Polynomial R"
    },
    {
      "name": "Polynomial.natDegree_hasseDeriv_le",
      "module_name": "Mathlib.Algebra.Polynomial.HasseDeriv",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] (p : Polynomial R) (n : ℕ),\n  ((Polynomial.hasseDeriv n) p).natDegree ≤ p.natDegree - n"
    },
    {
      "name": "MvPolynomial.mkDerivationₗ",
      "module_name": "Mathlib.Algebra.MvPolynomial.Derivation",
      "kind": "definition",
      "type": "{σ : Type u_1} →\n  (R : Type u_2) →\n    {A : Type u_3} →\n      [inst : CommSemiring R] →\n        [inst_1 : AddCommMonoid A] →\n          [inst_2 : Module R A] → [Module (MvPolynomial σ R) A] → (σ → A) → MvPolynomial σ R →ₗ[R] A"
    },
    {
      "name": "LaurentSeries.hasseDeriv",
      "module_name": "Mathlib.RingTheory.LaurentSeries",
      "kind": "definition",
      "type": "(R : Type u_2) →\n  {V : Type u_3} →\n    [inst : AddCommGroup V] → [inst_1 : Semiring R] → [inst_2 : Module R V] → ℕ → LaurentSeries V →ₗ[R] LaurentSeries V"
    },
    {
      "name": "Polynomial.hasseDeriv_apply",
      "module_name": "Mathlib.Algebra.Polynomial.HasseDeriv",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] (k : ℕ) (f : Polynomial R),\n  (Polynomial.hasseDeriv k) f = f.sum fun i r => (Polynomial.monomial (i - k)) (↑(i.choose k) * r)"
    },
    {
      "name": "Polynomial.hasseDeriv_coeff",
      "module_name": "Mathlib.Algebra.Polynomial.HasseDeriv",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] (k : ℕ) (f : Polynomial R) (n : ℕ),\n  ((Polynomial.hasseDeriv k) f).coeff n = ↑((n + k).choose k) * f.coeff (n + k)"
    }
  ]
}
